DELETE FROM `historias`;
INSERT INTO `historias` (`id`, `titulo`, `texto`, `imagem1`, `imagem2`, `data_criacao`, `ong_id`) VALUES
	(14, 'Mel', 'Mel era uma cachorrinha pequena que passou os primeiros anos de sua vida procurando por algo que nunca tinha conhecido de verdade: um lar.  Ela foi encontrada sozinha em uma rua movimentada, assustada e com fome. No começo, Mel tinha medo de se aproximar das pessoas. Sempre que alguém tentava fazer carinho nela, ela recuava, como se já tivesse aprendido que nem todos ficariam.  Quando foi resgatada, precisou de tempo para entender que estava segura. Aos poucos, começou a confiar novamente. Primeiro, aceitou um pouco de comida. Depois, um carinho tímido. Com o passar dos dias, sua personalidade alegre começou a aparecer.  Mel adorava correr, brincar e receber carinho. Mas ainda faltava algo: uma família.  Depois de alguns meses esperando, uma família conheceu Mel e se apaixonou por ela. No dia em que saiu do abrigo, parecia não acreditar que finalmente tinha encontrado um lugar para chamar de casa.  Hoje, Mel dorme em uma cama quentinha, brinca todos os dias e nunca mais precisou sentir', 'data:image/jpeg;base64,', NULL, '2026-09-01 16:43:38', 44);

